        prep: {"name": "store.py", "text": "import json\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\n\nclass MemoError(Exception):\n    \"\"\"메모 도구가 할 수 없는 일을 부탁받았을 때\"\"\"\n\n\n@dataclass\nclass Memo:\n    id: int\n    text: str\n\n\ndef load(path: Path) -> list[Memo]:\n    if not path.exists():\n        return []\n    with open(path, encoding=\"utf-8\") as f:\n        rows = json.load(f)\n    return [Memo(row[\"id\"], row[\"text\"]) for row in rows]\n\n\ndef save(path: Path, memos: list[Memo]) -> None:\n    rows = [{\"id\": m.id, \"text\": m.text} for m in memos]\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        json.dump(rows, f, ensure_ascii=False, indent=2)\n\n\ndef add(path: Path, text: str) -> Memo:\n    text = text.strip()\n    if not text:\n        raise MemoError(\"빈 메모는 저장할 수 없어요\")\n    memos = load(path)\n    new_id = memos[-1].id + 1 if memos else 1\n    memo = Memo(new_id, text)\n    memos.append(memo)\n    save(path, memos)\n    return memo\n\n\ndef find(path: Path, word: str) -> list[Memo]:\n    return [m for m in load(path) if word in m.text]\n\n\ndef remove(path: Path, memo_id: int) -> Memo:\n    memos = load(path)\n    for m in memos:\n        if m.id == memo_id:\n            memos.remove(m)\n            save(path, memos)\n            return m\n    raise MemoError(f\"{memo_id}번 메모가 없어요\")\n\n\nif __name__ == \"__main__\":\n    # ---- 써 보기: python store.py 로 직접 실행할 때만 ----\n    p = Path(\"memo_try.json\")\n    save(p, [])                       # 빈 메모장에서 시작\n    missing = load(Path(\"없는파일.json\"))\n    print(missing)\n    print(add(p, \" 우유 \"))\n    print(add(p, \"빵 사기\"))\n    print(find(p, \"우\"))\n    print(remove(p, 1))\n    print(load(p))\n    try:\n        add(p, \"   \")\n    except MemoError as e:\n        print(\"에러:\", e)\n    try:\n        remove(p, 9)\n    except MemoError as e:\n        print(\"에러:\", e)\n"},
