        given: "import tkinter as tk\n\n\nclass WaterApp:\n    def __init__(self, root):\n        self.cups = 0\n        self.label = tk.Label(root, text=\"오늘 물 0잔\", font=(\"맑은 고딕\", 16))\n        self.label.pack(padx=30, pady=10)\n        drink = tk.Button(root, text=\"한 잔 마셨어요\", command=self.drink())\n        drink.pack(pady=5)\n\n    def drink(self):\n        self.cups += 1\n        self.label.config(text=f\"오늘 물 {self.cups}잔\")\n\n\nroot = tk.Tk()\nroot.title(\"물 마시기\")\nWaterApp(root)\nroot.mainloop()\n",
        answer: "import tkinter as tk\n\n\nclass WaterApp:\n    def __init__(self, root):\n        self.cups = 0\n        self.label = tk.Label(root, text=\"오늘 물 0잔\", font=(\"맑은 고딕\", 16))\n        self.label.pack(padx=30, pady=10)\n        drink = tk.Button(root, text=\"한 잔 마셨어요\", command=self.drink)   # ← 괄호를 뺐어요\n        drink.pack(pady=5)\n        reset = tk.Button(root, text=\"처음부터\", command=self.reset)        # ← 더함\n        reset.pack(pady=5)\n\n    def drink(self):\n        self.cups += 1\n        self.label.config(text=f\"오늘 물 {self.cups}잔\")\n\n    def reset(self):                                                     # ← 더함\n        self.cups = 0\n        self.label.config(text=\"오늘 물 0잔\")\n\n\nroot = tk.Tk()\nroot.title(\"물 마시기\")\nWaterApp(root)\nroot.mainloop()\n",
