        answer: "import tkinter as tk\n\n\ndef split_bill(total_text, people_text):\n    try:\n        total = int(total_text.replace(\",\", \"\"))\n        people = int(people_text)\n    except ValueError:\n        return \"숫자로 넣어 주세요\"\n    if people < 1:\n        return \"사람 수는 1 이상이에요\"\n    share = total // people\n    rest = total % people\n    if rest:\n        return f\"한 사람 {share:,}원 · {rest}원 남아요\"\n    return f\"한 사람 {share:,}원\"\n\n\nassert split_bill(\"50000\", \"4\") == \"한 사람 12,500원\"\nassert split_bill(\"10,000\", \"3\") == \"한 사람 3,333원 · 1원 남아요\"\nassert split_bill(\"만원\", \"2\") == \"숫자로 넣어 주세요\"\nassert split_bill(\"9000\", \"0\") == \"사람 수는 1 이상이에요\"\n\n\ndef on_split():\n    msg = split_bill(total_entry.get(), people_entry.get())\n    result.config(text=msg)\n\n\nroot = tk.Tk()\nroot.title(\"더치페이\")\n\ntk.Label(root, text=\"모두 낸 돈(원)\").pack(pady=(10, 0))\ntotal_entry = tk.Entry(root, width=15, font=(\"맑은 고딕\", 14))\ntotal_entry.pack()\n\ntk.Label(root, text=\"사람 수\").pack(pady=(10, 0))\npeople_entry = tk.Entry(root, width=15, font=(\"맑은 고딕\", 14))\npeople_entry.pack()\n\ntk.Button(root, text=\"나누기\", command=on_split).pack(pady=10)\n\nresult = tk.Label(root, text=\"\", font=(\"맑은 고딕\", 16))\nresult.pack(padx=20, pady=(0, 10))\n\nroot.mainloop()\n",
