        answer: "DIRS = [(1, 0), (0, 1), (-1, 0), (0, -1)]   # 아래 · 오른쪽 · 위 · 왼쪽\n\n\ndef can_go(grid, r, c):\n    if not 0 <= r < len(grid):\n        return False\n    if not 0 <= c < len(grid[r]):\n        return False\n    return grid[r][c] in \".E\"\n\n\ndef solve(grid, r, c):\n    if grid[r][c] == \"E\":\n        return True\n    if grid[r][c] == \".\":\n        grid[r][c] = \"*\"\n    for dr, dc in DIRS:\n        nr = r + dr\n        nc = c + dc\n        if can_go(grid, nr, nc) and solve(grid, nr, nc):\n            return True\n    if grid[r][c] == \"*\":\n        grid[r][c] = \"x\"\n    return False\n\n\nrows = [\n    \"######\",\n    \"#S..##\",\n    \"#.#..#\",\n    \"#.#.##\",\n    \"#...E#\",\n    \"######\",\n]\ngrid = [list(row) for row in rows]\nprint(solve(grid, 1, 1))\nfor row in grid:\n    print(\"\".join(row))\n",
