        answer: "import sys\n\nDIRS = [(0, 1), (1, 0), (0, -1), (-1, 0)]   # 오른쪽 · 아래 · 왼쪽 · 위\n\n\ndef load(path):\n    with open(path, encoding=\"utf-8\") as f:\n        return [list(line.rstrip(\"\\n\")) for line in f if line.strip()]\n\n\ndef find(grid, ch):\n    for r, row in enumerate(grid):\n        for c, x in enumerate(row):\n            if x == ch:\n                return r, c\n    return None\n\n\ndef can_go(grid, r, c):\n    if not 0 <= r < len(grid):\n        return False\n    if not 0 <= c < len(grid[r]):\n        return False\n    return grid[r][c] in \".E\"\n\n\ndef solve(grid, r, c):\n    if grid[r][c] == \"E\":\n        return True\n    if grid[r][c] == \".\":\n        grid[r][c] = \"*\"\n    for dr, dc in DIRS:\n        nr = r + dr\n        nc = c + dc\n        if can_go(grid, nr, nc) and solve(grid, nr, nc):\n            return True\n    if grid[r][c] == \"*\":\n        grid[r][c] = \"x\"\n    return False\n\n\ndef count(grid, ch):\n    return sum(row.count(ch) for row in grid)\n\n\ndef clean(grid):\n    for row in grid:\n        for i, x in enumerate(row):\n            if x == \"x\":\n                row[i] = \".\"\n\n\ngrid = load(\"maze.txt\")\nstart = find(grid, \"S\")\nif start is None or find(grid, \"E\") is None:\n    print(\"S 와 E 가 다 있어야 해요\")\n    sys.exit(1)\nr, c = start\nif solve(grid, r, c):\n    back = count(grid, \"x\")\n    clean(grid)\n    for row in grid:\n        print(\"\".join(row))\n    print(f\"길: {count(grid, '*')}칸 · 갔다가 돌아온 칸: {back}칸\")\nelse:\n    print(\"길이 없어요\")\n",
